  function categories(){
    const supplied=Array.isArray(GUIDE.categories)?GUIDE.categories:Array.isArray(GUIDE.categoryTree)?GUIDE.categoryTree:Array.isArray(GUIDE.knowledgeTree)?GUIDE.knowledgeTree:[];
    if(!supplied.length)return FALLBACK_CATEGORIES;
    const aliases={police:'public-security-judicial',medical:'rural-medical'};
    return FALLBACK_CATEGORIES.map(base=>{const match=supplied.find(item=>item.id===base.id||item.id===aliases[base.id]||item.categoryId===base.id||item.title===base.title||item.label===base.title);return match?{...base,...match,id:base.id,title:match.title||match.label||match.name||base.title,subcategories:match.subcategories||match.children||base.subcategories}:base});
  }
  function categoryById(id){return categories().find(item=>item.id===id)||categories()[0]}
  function groupCountForCategory(category){if(!category.groupIds?.length)return null;return GROUPS.filter(group=>category.groupIds.includes(group.categoryId)).length}
  function selectedGroupCount(){return state.record?.selectedGroupKeys?.length||0}
  function scoreSummary(student=state.currentStudent){if(!student)return'尚未选择学生';const p=state.record?.profile||{};const subject=p.subjectType||normalizeSubject(student.subject_type)||'选科待补';const electives=unique(p.electives||[]);const score=p.score||studentValue(student,'gaokao_score','estimated_score','score');const rank=p.rank||studentValue(student,'gaokao_rank','estimated_rank','rank');return`${subject}${electives.length?'｜'+electives.join('+'):''}${score?`｜${score} 分`:''}${rank?`｜位次 ${rank}`:''}`}
