    const conflictStatusOptions=current=>[['','未复核'],['researching','查找2026官方文件'],['conflict_unresolved','官方文件仍未关闭冲突'],['official_verified','已用2026官方文件人工核验'],['not_applicable','该学生不适用']].map(([value,label])=>`<option value="${value}" ${current===value?'selected':''}>${label}</option>`).join('');
